    """SPEC 6.3's string form. ``None`` means UNKNOWN.

    A naive ``datetime`` is rendered as it stands rather than assumed to be
    UTC: the core does not invent facts (SPEC 1.3), and every timestamp that
    reached a record through the pipeline is aware already.
    """
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, Level):
        return value.name
    if isinstance(value, str):
        return value
    if isinstance(value, datetime):
        if is_naive(value):
            return value.isoformat()
        return value.astimezone(timezone.utc).isoformat()
    if isinstance(value, (int, float)):
        return str(value)
    return None


def _compare_ordered(op: str, left: float | str | datetime, right: object) -> Kleene:
    """Apply an ordering or equality operator to two same-typed values."""
    if op == "==":
        return from_bool(left == right)
    if op == "!=":
        return from_bool(left != right)
    if op == "<":
        return from_bool(left < right)  # type: ignore[operator]
    if op == "<=":
        return from_bool(left <= right)  # type: ignore[operator]
    if op == ">":
        return from_bool(left > right)  # type: ignore[operator]
    return from_bool(left >= right)  # type: ignore[operator]


@dataclass(slots=True)
class Context:
    """What evaluation needs beyond the record itself.

    ``fields_seen`` is what feeds SPEC 6.5's "referenced but never present"
    warning; collecting it here is why the pipeline needs no extra state.
    """

    assume_tz: tzinfo = timezone.utc
    fields_seen: set[str] = field(default_factory=set)


def evaluate(node: Node, record: Record, ctx: Context) -> Kleene:
    """Evaluate an AST against one record. Total: never raises."""
    if isinstance(node, Cmp):
        return _evaluate_cmp(node, record, ctx)
    if isinstance(node, Not):
        return k_not(evaluate(node.operand, record, ctx))
    if isinstance(node, And):
        return k_and(
            evaluate(node.left, record, ctx), evaluate(node.right, record, ctx)
        )
    return k_or(evaluate(node.left, record, ctx), evaluate(node.right, record, ctx))


def _evaluate_cmp(node: Cmp, record: Record, ctx: Context) -> Kleene:
    value = resolve_field(record, node.name)
    if value is MISSING:
        return Kleene.UNKNOWN
    ctx.fields_seen.add(node.name)
    if node.regex is not None:
        text = render_filter_str(value)
        return (
            Kleene.UNKNOWN
            if text is None
            else from_bool(node.regex.search(text) is not None)
        )
    return _compare(node.op, node.literal, value, ctx)


def _compare(op: str, literal: Literal, value: object, ctx: Context) -> Kleene:
    if literal.mode is Mode.NUMERIC:
        number = coerce_number(value)
        if number is None:
            return Kleene.UNKNOWN
        assert isinstance(literal.value, float)
        return _compare_ordered(op, number, literal.value)

    if literal.mode is Mode.STRING:
        text = render_filter_str(value)
        if text is None:
            return Kleene.UNKNOWN
        return _compare_ordered(op, text, literal.value)

    if literal.mode is Mode.BOOLEAN:
        if not isinstance(value, bool):
            return Kleene.UNKNOWN
        if op == "==":
            return from_bool(value == literal.value)
        if op == "!=":
            return from_bool(value != literal.value)
        # Ordering a boolean has no meaning, and SPEC 6.3 says so rather than
        # falling back on False < True.
        return Kleene.UNKNOWN

    if literal.mode is Mode.LEVEL:
        if not isinstance(value, Level):
            return Kleene.UNKNOWN
        assert isinstance(literal.value, Level)
        return _compare_ordered(op, value.value, literal.value.value)

    if not isinstance(value, datetime):
        return Kleene.UNKNOWN
    assert isinstance(literal.value, datetime)
    left = _to_comparable_utc(value, ctx)
    right = _to_comparable_utc(literal.value, ctx)
    if left is None or right is None:
        return Kleene.UNKNOWN
    return _compare_ordered(op, left, right)


def _to_comparable_utc(value: datetime, ctx: Context) -> datetime | None:
    """UTC form of ``value``, localizing a naive one with ``--assume-tz``.

    Both sides go through this, so a naive literal and a naive field value are
    interpreted the same way (SPEC 6.3, temporal). ``None`` on overflow at the
    edges of the ``datetime`` domain, which is UNKNOWN rather than a crash.
    """
    try:
        if is_naive(value):
            value = value.replace(tzinfo=ctx.assume_tz)
        return value.astimezone(timezone.utc)
    except (OverflowError, ValueError, TypeError, OSError):
        return None
"""The filter language: ``compile(text)`` and the predicate it returns.

SPEC 6. Everything the rest of logsift needs from the expression pipeline is
here; the CLI never touches the lexer, and the pipeline never touches the AST.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import timezone, tzinfo

from logsift.expr.eval import (
    Context,
    Kleene,
    coerce_number,
    evaluate,
    render_filter_str,
    resolve_field,
)
from logsift.expr.lexer import FilterSyntaxError
from logsift.expr.parser import And, Cmp, Node, Not, Or, parse, unparse
from logsift.record import Record

__all__ = [
    "CompiledFilter",
    "FilterSyntaxError",
    "Kleene",
    "coerce_number",
    "compile",
    "render_filter_str",
    "resolve_field",
    "unparse",
]


@dataclass(slots=True)
class CompiledFilter:
    """A parsed expression bound to the zone naive literals are read in.

    ``fields_seen`` accumulates every referenced name that was actually
    present on some record. The difference from :attr:`field_names` is SPEC
    6.5's "referenced but never present" warning, which is what turns a typo
    into a visible message instead of a silent empty result.
    """

    node: Node
    text: str
    field_names: frozenset[str]
    _ctx: Context = field(repr=False)

    @property
    def fields_seen(self) -> set[str]:
        return self._ctx.fields_seen

    @property
    def unseen_fields(self) -> frozenset[str]:
        return self.field_names - self._ctx.fields_seen

    def evaluate(self, record: Record) -> Kleene:
        return evaluate(self.node, record, self._ctx)

    def matches(self, record: Record) -> bool:
        """TRUE only. UNKNOWN does not emit a record (SPEC 6.4)."""
        return self.evaluate(record) is Kleene.TRUE


# Shadows the builtin inside this module only. `expr.compile(text)` is the
# name the rest of logsift calls, and `compile_filter` would stutter at every
# call site; nothing here needs the builtin.
def compile(text: str, *, assume_tz: tzinfo | None = None) -> CompiledFilter:
    """Parse ``text`` into a filter, raising :class:`FilterSyntaxError`.

    ``assume_tz`` is the zone a temporal literal without an offset is read in
    (SPEC 6.3). It defaults to UTC rather than the system zone: the CLI always
    passes the resolved ``--assume-tz``, and a library caller should not get a
    filter whose meaning depends on the machine.
    """
    node = parse(text)
    return CompiledFilter(
        node=node,
        text=text,
        field_names=frozenset(_names(node)),
        _ctx=Context(assume_tz=assume_tz if assume_tz is not None else timezone.utc),
    )


def _names(node: Node) -> set[str]:
    if isinstance(node, Cmp):
        return {node.name}
    if isinstance(node, Not):
        return _names(node.operand)
    if isinstance(node, (And, Or)):
        return _names(node.left) | _names(node.right)
    return set()  # pragma: no cover - Node is exhausted above
"""ISO 8601 reading and time zone helpers (SPEC sections 2.1 and 7).

``datetime.fromisoformat`` on Python 3.10 refuses a trailing ``Z`` and any
fractional-second length other than 3 or 6 digits, so the core owns its own
reader. It is used by the filter language, by the pipeline, and by any parser
that wants it.

Everything here is pure. The one-time "assuming timezone X" diagnostic of
SPEC 7 is emitted by ``pipeline``, which owns diagnostics; keeping it out of
this module is what lets these functions be property-tested.
"""

from __future__ import annotations

import re
from datetime import datetime, timedelta, timezone, tzinfo
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

# Extended format only, and ASCII digits only: `\d` also matches Arabic-Indic
# and other Unicode digits, which `int()` would happily accept.
_DATE = r"(?P<year>[0-9]{4})-(?P<month>[0-9]{2})-(?P<day>[0-9]{2})"
_TIME = (
    r"(?P<hour>[0-9]{2}):(?P<minute>[0-9]{2})"
    r"(?::(?P<second>[0-9]{2})(?:\.(?P<fraction>[0-9]{1,9}))?)?"
)
_OFFSET = r"(?P<offset>[Zz]|[+-][0-9]{2}(?::?[0-9]{2})?)"
# An offset needs a time to attach to, so the whole tail is one optional group.
_ISO_RE = re.compile(rf"{_DATE}(?:[Tt ]{_TIME}{_OFFSET}?)?")

_MICROSECOND_DIGITS = 6


class UnknownZone(Exception):
    """``--assume-tz`` or ``--tz`` named an unusable zone; the CLI exits 2."""


def parse_iso8601(text: str) -> datetime | None:
    """Read an ISO 8601 timestamp, or return ``None``. Never raises.

    Accepted::

        YYYY-MM-DD[(T|t|space)HH:MM[:SS[.f{1,9}]][offset]]

    where *offset* is ``Z``, ``z``, ``+HH:MM``, ``+HHMM``, or ``+HH`` (and the
    ``-`` forms). A bare date is midnight, matching ``fromisoformat``. Without
    an offset the result is **naive**; SPEC 7 leaves it to the core to decide
    what zone that means.

    Fractional digits past the sixth are truncated rather than rounded,
    because a ``datetime`` stores microseconds and logsift will not invent
    precision it cannot hold. Deliberately outside the grammar: basic format
    (``20260901T100000Z``), ``24:00`` end-of-day, leap second ``:60``, comma
    fractions, offsets with seconds, and surrounding whitespace. Each of those
    returns ``None``, which for a parser means the raw string is kept instead.
    """
    match = _ISO_RE.fullmatch(text)
    if match is None:
        return None

    offset = match["offset"]
    if offset is None:
        zone = None
    else:
        zone = _offset_zone(offset)
        if zone is None:
            return None

    fraction = match["fraction"]
    microsecond = (
        int(fraction.ljust(_MICROSECOND_DIGITS, "0")[:_MICROSECOND_DIGITS])
        if fraction is not None
        else 0
    )

    try:
        return datetime(
            int(match["year"]),
            int(match["month"]),
            int(match["day"]),
            int(match["hour"] or 0),
            int(match["minute"] or 0),
            int(match["second"] or 0),
            microsecond,
            tzinfo=zone,
        )
    except ValueError:
        # Month 13, 30 February, hour 24, a leap second: the shape was right
        # and the values were not.
        return None


def _offset_zone(text: str) -> timezone | None:
    """Turn a matched offset into a fixed zone, or ``None`` if out of range."""
    if text in ("Z", "z"):
        return timezone.utc
    digits = text[1:].replace(":", "")
    hours = int(digits[:2])
    minutes = int(digits[2:]) if digits[2:] else 0
    if hours > 23 or minutes > 59:
        return None
    delta = timedelta(hours=hours, minutes=minutes)
    return timezone(-delta if text[0] == "-" else delta)


def is_naive(dt: datetime) -> bool:
    """Whether ``dt`` carries no usable offset.

    A ``tzinfo`` whose ``utcoffset()`` returns ``None`` is naive in every way
    that matters: ``astimezone`` cannot convert it. One implementation, so the
    subtlety is not re-derived at each call site.
    """
    return dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None


def to_utc(dt: datetime, assume_tz: tzinfo) -> datetime | None:
    """Normalize to UTC, localizing a naive ``dt`` with ``assume_tz`` (SPEC 7).

    An aware ``dt`` is converted and ``assume_tz`` is ignored. Localization
    keeps ``dt.fold``, which defaults to 0, so an ambiguous local time (the
    repeated hour when DST ends) reads as the *first* of the two and a
    nonexistent one (the skipped hour when DST starts) takes the offset in
    force before the gap. That is a documented choice, not a guess: logsift
    has nothing in the log to disambiguate with.

    ``None`` means the shifted timestamp falls outside the ``datetime``
    domain, which happens within a day of year 1 and year 9999 -- and
    ``9999-12-31`` is a popular "never expires" sentinel. The caller has no
    timestamp to work with in that case, but the line is still a line, so this
    is a value rather than an exception.
    """
    if is_naive(dt):
        dt = dt.replace(tzinfo=assume_tz)
    try:
        return dt.astimezone(timezone.utc)
    except OverflowError:
        return None


def resolve_zone(name: str) -> ZoneInfo:
    """Look up an IANA zone name for ``--assume-tz`` / ``--tz``.

    Raises :class:`UnknownZone` for a name the system's tzdata does not
    provide, and for one ``zoneinfo`` rejects outright (absolute or traversing
    paths). A genuine I/O failure reading tzdata is left to propagate: that is
    a broken system, not a bad zone name.
    """
    try:
        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError) as exc:
        raise UnknownZone(f"unknown timezone {name!r}: {exc}") from exc


def local_zone() -> tzinfo:
    """The system local zone, the default for ``--assume-tz`` (SPEC 7).

    This is a *fixed offset* taken from the current moment, because the
    standard library cannot name the local IANA zone and ``zoneinfo`` cannot
    reverse-lookup one from an offset. A log written on the other side of a
    DST transition is therefore localized with today's offset; pass
    ``--assume-tz`` to get a zone that knows its own history. The stderr line
    that reports the assumption is what keeps this visible.
    """
    zone = datetime.now().astimezone().tzinfo
    if zone is None:  # pragma: no cover - astimezone() is always aware
        return timezone.utc
    return zone


def zone_label(zone: tzinfo) -> str:
    """A name for ``zone`` to print in a diagnostic.

    An IANA key when there is one, otherwise the abbreviation the zone reports
    for now (``PKT``), which is what :func:`local_zone` can offer.
    """
    if isinstance(zone, ZoneInfo):
        return zone.key
    return zone.tzname(datetime.now()) or str(zone)
"""Shared fixtures and the helpers the parser tests have in common.

``install_dist`` writes a real ``.dist-info`` directory onto ``sys.path`` so
that ``importlib.metadata.entry_points`` finds it exactly as it would find an
installed wheel. Nothing in the plugin tests monkeypatches discovery itself.
"""

from __future__ import annotations

import importlib
from collections.abc import Iterator, Mapping, Sequence
from datetime import datetime
from pathlib import Path
from typing import Protocol

import pytest

from logsift.plugin import Parser
from logsift.record import Level, Record

TESTS_DIR = Path(__file__).parent
FIXTURES_DIR = TESTS_DIR / "fixtures"

METADATA = "Metadata-Version: 2.1\nName: {name}\nVersion: {version}\n"


def fixture_lines(name: str) -> list[str]:
    """Every non-empty line of a fixture file, newline stripped (SPEC 4.2)."""
    text = (FIXTURES_DIR / name).read_text()
    return [line for line in text.splitlines() if line.strip()]


def records_for(parser: Parser, lines: Sequence[str], *, source: str) -> list[Record]:
    """Build records the way SPEC 3 and 4.3 say the core will.

    ``pipeline`` does not exist yet, so this is the smallest stand-in for the
    one rule the parser tests need from it: ``None`` from ``parse`` becomes a
    parse-error record, anything else becomes an ordinary one. The fixtures
    carry no blank lines, so the index is the file's own line number.
    """
    records: list[Record] = []
    for lineno, line in enumerate(lines, start=1):
        result = parser.parse(line)
        if result is None:
            records.append(
                Record.parse_error_record(
                    raw=line,
                    source=source,
                    lineno=lineno,
                    reason="parser returned None",
                )
            )
            continue
        records.append(
            Record(
                raw=line,
                source=source,
                lineno=lineno,
                ts=result.ts,
                level=result.level,
                message=result.message,
                fields=result.fields,
                parse_error=False,
                parse_error_reason=None,
            )
        )
    return records


def make_record(
    *,
    raw: str = "a line",
    source: str = "app.log",
    lineno: int = 1,
    ts: datetime | None = None,
    level: Level | None = None,
    message: str | None = None,
    fields: Mapping[str, object] | None = None,
    parse_error: bool = False,
    parse_error_reason: str | None = None,
) -> Record:
    """A record with everything defaulted, for tests that care about one field."""
    return Record(
        raw=raw,
        source=source,
        lineno=lineno,
        ts=ts,
        level=level,
        message=message,
        fields={} if fields is None else fields,
        parse_error=parse_error,
        parse_error_reason=parse_error_reason,
    )


class InstallDist(Protocol):
    """Publish ``entries`` as ``logsift.parsers`` entry points of ``dist``."""

    def __call__(
        self, dist: str, entries: Mapping[str, str], *, version: str = "1.0"
    ) -> Path: ...


@pytest.fixture
def install_dist(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> Iterator[InstallDist]:
    site = tmp_path / "site-packages"
    site.mkdir()
    # The fake parsers themselves live in the test tree, not in the fake site
    # directory; only their distribution metadata is synthesized.
    monkeypatch.syspath_prepend(str(TESTS_DIR))
    monkeypatch.syspath_prepend(str(site))

    def install(dist: str, entries: Mapping[str, str], *, version: str = "1.0") -> Path:
        info = site / f"{dist.replace('-', '_')}-{version}.dist-info"
